usage.code:
import { Folder } from "solen-design/react";

const items = [
  { title: "Brand guidelines", description: "Colors, type and voice" },
  { title: "Launch plan", description: "Milestones and owners" },
  { title: "Moodboard" }
];

<Folder
  label="Projects"
  items={items}
  mode="flap"
  variant="solid"
  color="#3d8bff"
  paperColor="#ffffff"
  tabPosition="right"
  layout="spread"
  size={1}
  openOn="click"
  peek={true}
  draggable={true}
  zoomOnClick={true}
  intro={true}
  tilt={0.5}
  bounce={0.4}
  speed={1}
  theme="dark"
  onItemClick={(item, index) => console.log(index, item.title)}
  onItemDrop={(item, index, intoFolder) => console.log(index, intoFolder)}
/>
